import 'package:labwright/shims.dart' as ts;

double fakeSerialNumber = 28;

class _MainSequenceLocals {
  int cycle = 0;
  int capacity = 2000;
  String filePath = '';
}

Future<ts.Status> mainSequence() async {
  final locals = _MainSequenceLocals();
  final run = ts.SequenceRun();
  dynamic chargeAndDischargeResult = ts.StepResult();

  await ts.stepType('AddProperty', {'KeyExpr': '"Location"', 'ValueExpr': '"Austin"'});
  await ts.stepType('AddProperty', {'KeyExpr': '"Voltage (V)"', 'ValueExpr': '"1.5"'});
  await ts.stepType('AddProperty', {'KeyExpr': '"Capacity (mAh)"', 'ValueExpr': 'Str(Locals.Capacity)'});
  await ts.stepType('AddProperty', {'KeyExpr': '"Composition"', 'ValueExpr': '"NiMH"'});
  await ts.stepType('EmailNotification', {
    'SendOnErrored': true,
    'SendOnFailed': true,
    'SendOnTerminated': true,
    'SendOnPassed': true,
    'RecipientExpr': 'Locals.EmailAddress',
  });
  for (locals.cycle = 0; locals.cycle < 500; locals.cycle += 1) {
    chargeAndDischargeResult = ts.StepResult();
    final outputs = await ts.callVi(
      'My Computer\\Charge and Discharge.vi',
      inputs: {'Cycle': locals.cycle, 'Initial Capacity  (mAh)': locals.capacity, 'TDMS File Path In': locals.filePath},
    ); // Charge and Discharge
    locals.filePath = outputs['TDMS File Path'] as String;
    chargeAndDischargeResult.Status = ts.multipleNumericLimitTest([
      (value: outputs['Capacity (mAh)'], comparison: 'GT', low: 100, high: 11),
      (value: outputs['Energy (Wh)'], comparison: 'GT', low: 100, high: 11),
    ]);
    run.record(chargeAndDischargeResult.Status);
  }
  await ts.stepType('UploadFile', {'FilePathExpr': 'Locals.FilePath'});

  return run.status;
}

